import{_ as i,o as a,c as t,a6 as r}from"./chunks/framework.DL_pga9_.js";const m=JSON.parse('{"title":"Auto Traits And Derive Traits","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/auto_derive_traits_baseline.md","filePath":"design/archive/auto_derive_traits_baseline.md","lastUpdated":1780030916000}'),o={name:"design/archive/auto_derive_traits_baseline.md"};function l(s,e,d,n,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="auto-traits-and-derive-traits" tabindex="-1">Auto Traits And Derive Traits <a class="header-anchor" href="#auto-traits-and-derive-traits" aria-label="Permalink to “Auto Traits And Derive Traits”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 7.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Add compiler-assisted trait implementation mechanisms for common marker and structural traits.</p><p>Example direction:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Point: derive(Copy + Clone) {</span></span>
<span class="line"><span>  x: i32;</span></span>
<span class="line"><span>  y: i32;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auto trait Send;</span></span></code></pre></div><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li><a href="./module_artifact_typechecker">Module Artifact And Typechecker Integration</a>, for cross-module trait impl visibility and coherence.</li><li><a href="./generalized_delete">Generalized <code>= delete</code> Declarations</a>, for negative or blocked auto-trait behavior.</li><li>Existing trait dispatch, trait bounds, and impl coherence.</li></ul><p>Related:</p><ul><li><a href="./stdlib_modularization">Standard Library Modularization</a>, if core marker traits live in <code>std</code>.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li>Syntax and semantics for <code>derive(...)</code>.</li><li>Syntax and semantics for <code>auto trait</code>.</li><li>Built-in derive support for a small initial set, initially <code>Copy</code> and <code>Clone</code>.</li><li>Structural eligibility checks.</li><li>Interaction with explicit impls and coherence.</li><li>Diagnostics explaining why derive/auto trait application failed.</li></ul><p>Out of scope:</p><ul><li>Procedural macros.</li><li>User-defined derive expansion hooks.</li><li>Associated types.</li><li>Runtime generation for user-defined derive hooks.</li></ul><h2 id="semantics" tabindex="-1">Semantics <a class="header-anchor" href="#semantics" aria-label="Permalink to “Semantics”">​</a></h2><p><code>derive(...)</code> is explicit implementation evidence for compiler-supported traits. It is not the same mechanism as an auto trait. A structural type with copyable fields does not satisfy <code>T: Copy</code> unless it declares <code>derive(Copy)</code> or has an explicit <code>impl Copy for T</code>.</p><p><code>auto trait Name;</code> declares a methodless marker trait whose implementation is computed structurally. A type satisfies an auto trait when every reachable field type also satisfies it, unless a future negative impl/delete rule blocks that propagation.</p><p>Built-in scalar values, strings, unit, references, fixed arrays, spans, and tuples participate structurally. <code>vector&lt;T&gt;</code> is intentionally not <code>Copy</code> through derive eligibility because it owns dynamic storage.</p><p><code>derive(Copy)</code> conflicts with <code>Drop</code>, because copying a value with deterministic destruction would make ownership ambiguous. Explicit impls and derived impls for the same <code>(trait, type)</code> pair are also deterministic coherence conflicts.</p><h2 id="phased-implementation-plan" tabindex="-1">Phased Implementation Plan <a class="header-anchor" href="#phased-implementation-plan" aria-label="Permalink to “Phased Implementation Plan”">​</a></h2><h3 id="phase-1-parser-and-typechecker-evidence" tabindex="-1">Phase 1: Parser And Typechecker Evidence <a class="header-anchor" href="#phase-1-parser-and-typechecker-evidence" aria-label="Permalink to “Phase 1: Parser And Typechecker Evidence”">​</a></h3><ul><li>Implemented: <code>auto trait Name;</code> syntax.</li><li>Implemented: parser support for <code>auto trait</code> declarations with optional supertraits and method bodies, so the typechecker can reject invalid auto traits with diagnostics.</li><li>Implemented: <code>type Name: derive(Copy + Clone) { ... }</code> syntax for structural type definitions.</li><li>Implemented: typechecker validation that auto traits have no generic parameters and no methods.</li><li>Implemented: structural auto trait satisfaction for primitive, reference, tuple, array, vector, span, and structural field graphs.</li><li>Implemented: derive eligibility checks for <code>Copy</code> and <code>Clone</code>.</li><li>Implemented: derived impl evidence for trait bounds and explicit-impl coherence.</li><li>Implemented: <code>Drop</code> conflict checks for derived <code>Copy</code>.</li><li>Implemented: STUPID and ORGASM example coverage through <code>example/55.auto_derive_traits.ng</code>.</li><li>Implemented: <code>derive(Clone)</code> exposes a callable <code>clone()</code> method.</li></ul><h3 id="phase-2-synthetic-runtime-bodies" tabindex="-1">Phase 2: Synthetic Runtime Bodies <a class="header-anchor" href="#phase-2-synthetic-runtime-bodies" aria-label="Permalink to “Phase 2: Synthetic Runtime Bodies”">​</a></h3><ul><li>Implemented: a derived <code>Clone::clone(self: ref&lt;Self&gt;) -&gt; Self</code> body is synthesized for structural types.</li><li>Implemented: STUPID and ORGASM lower the synthetic method through the same runtime dispatch path.</li><li>Remaining: ensure synthetic clone behavior respects future partial-move initialization state semantics.</li><li>Implemented: tests call a derived <code>clone()</code> method directly.</li></ul><h3 id="phase-3-debug-show-like-derived-traits" tabindex="-1">Phase 3: Debug/Show-Like Derived Traits <a class="header-anchor" href="#phase-3-debug-show-like-derived-traits" aria-label="Permalink to “Phase 3: Debug/Show-Like Derived Traits”">​</a></h3><ul><li>Define the standard trait shape for <code>Debug</code> or <code>Show</code>.</li><li>Generate deterministic field-order formatting.</li><li>Decide whether formatting traits are standard-library traits, compiler-known traits, or both.</li><li>Add examples covering nested structural types and tuples.</li></ul><h3 id="phase-4-negative-auto-trait-controls" tabindex="-1">Phase 4: Negative Auto Trait Controls <a class="header-anchor" href="#phase-4-negative-auto-trait-controls" aria-label="Permalink to “Phase 4: Negative Auto Trait Controls”">​</a></h3><ul><li>Integrate generalized <code>= delete</code> or negative impl rules.</li><li>Allow a type to block auto trait propagation intentionally.</li><li>Add diagnostics that identify the field path that prevents propagation.</li></ul><h3 id="phase-5-module-artifact-export" tabindex="-1">Phase 5: Module Artifact Export <a class="header-anchor" href="#phase-5-module-artifact-export" aria-label="Permalink to “Phase 5: Module Artifact Export”">​</a></h3><ul><li>Persist auto trait definitions and derived impl evidence into module artifacts.</li><li>Ensure imported modules expose the same trait satisfaction results as source modules.</li><li>Reject cross-module coherence conflicts deterministically.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li><code>auto trait Send;</code> parses and a structural type with only sendable fields satisfies <code>T: Send</code>.</li><li><code>type Point: derive(Copy + Clone) { x: i32; y: i32; }</code> parses and satisfies <code>T: Copy</code> and <code>T: Clone</code>.</li><li><code>derive(Clone)</code> synthesizes a callable <code>clone(self: ref&lt;Self&gt;) -&gt; Self</code> method in both STUPID and ORGASM.</li><li>A structural type without <code>derive(Copy)</code> or explicit <code>impl Copy</code> does not satisfy <code>T: Copy</code>.</li><li><code>derive(Copy)</code> rejects fields that cannot be copied, such as <code>vector&lt;T&gt;</code>.</li><li>Explicit impls conflict deterministically with derived impls.</li><li><code>Drop</code> conflicts deterministically with derived <code>Copy</code>.</li><li>Invalid auto traits with generic parameters or methods fail during type checking.</li><li>Negative or blocked auto-trait behavior is specified before implementation.</li></ul>`,35)])])}const u=i(o,[["render",l]]);export{m as __pageData,u as default};
